std::string trim(std::string s){ auto a=s.find_first_not_of(" \t\n\r"); auto b=s.find_last_not_of(" \t\n\r"); return a==std::string::npos?"":s.substr(a,b-a+1); }
std::string lowercase(std::string s){ std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));}); return s; }
std::string read1(const std::string&p){ std::ifstream f(p); std::string s; std::getline(f,s); return trim(s); }
